package com.tradelens.ta

import com.tradelens.data.model.Candle
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import kotlin.math.abs
import kotlin.math.max

/**
 * Cross-checks every indicator against the open-source `ta` library (bukosabino/ta 0.11.0) on 3,000 synthetic
 * bars with gaps, a flat stretch and volume spikes. Fixtures: src/test/resources/ta, generated by
 * tools/ta-reference/generate_reference.py.
 *
 *  - Exact-convention indicators must match to ~1e-6 relative on every bar.
 *  - Seed-convention differences (SMA-seeded vs pandas ewm-seeded) must converge: compared after [LATE].
 */
class ReferenceImplementationTest {

    companion object {
        val candles: List<Candle> by lazy {
            res("candles.csv").drop(1).map { l ->
                val p = l.split(",")
                Candle(p[0].toLong(), p[1].toDouble(), p[2].toDouble(), p[3].toDouble(), p[4].toDouble(), p[5].toDouble().toLong())
            }
        }
        val ref: Map<String, List<Double?>> by lazy {
            val rows = res("reference.csv")
            val head = rows.first().split(",")
            val cols = head.associateWith { mutableListOf<Double?>() }
            rows.drop(1).forEach { r -> r.split(",").forEachIndexed { k, v -> cols[head[k]]!!.add(v.toDoubleOrNull()) } }
            cols
        }
        private fun res(name: String) =
            ReferenceImplementationTest::class.java.getResourceAsStream("/ta/$name")!!.bufferedReader().readLines().filter { it.isNotBlank() }
        const val LATE = 1200      // ≫ 3 × the longest EMA period, so seed differences have decayed below tolerance
    }

    private val close get() = candles.map { it.close }

    private fun check(name: String, mine: List<Double?>, col: String, from: Int = 0, tol: Double = 1e-6, scale: Double = 1.0) {
        val theirs = ref.getValue(col)
        var compared = 0
        var worst = 0.0
        for (i in from until candles.size) {
            val a = mine[i] ?: continue
            val b = theirs[i]?.times(scale) ?: continue
            if (!b.isFinite()) continue
            val err = abs(a - b) / max(1.0, abs(b))
            if (err > worst) worst = err
            if (err > tol) fail("$name vs ta.$col at bar $i: mine=$a ta=$b (rel err $err > $tol)")
            compared++
        }
        assertTrue("$name: too few bars compared ($compared)", compared > 500)
    }

    @Test fun smaMatchesExactly() { for (p in listOf(50, 100, 200)) check("SMA$p", Rolling.sma(close, p), "sma$p") }

    @Test fun emaConvergesToPandasSeed() { for (p in listOf(9, 20, 21, 50, 100, 200)) check("EMA$p", Rolling.ema(close, p), "ema$p", from = LATE) }

    @Test fun atrMatchesExactly() {
        check("ATR14", VolatilityCalc.atr(candles, 14), "atr")
        check("ATR10", VolatilityCalc.atr(candles, 10), "atr10")
    }

    @Test fun bollingerMatchesExactly() {
        val b = VolatilityCalc.bollinger(close)
        check("BB mid", b.mid, "bb_mid"); check("BB upper", b.upper, "bb_upper"); check("BB lower", b.lower, "bb_lower")
    }

    @Test fun keltnerConverges() {
        val k = VolatilityCalc.keltner(candles)
        check("KC mid", k.mid, "kc_mid", from = LATE); check("KC upper", k.upper, "kc_upper", from = LATE); check("KC lower", k.lower, "kc_lower", from = LATE)
    }

    @Test fun donchianMatchesExactly() {
        val d = VolatilityCalc.donchian(candles)
        check("DC upper", d.upper, "dc_upper"); check("DC lower", d.lower, "dc_lower"); check("DC mid", d.mid, "dc_mid")
    }

    @Test fun rsiConverges() = check("RSI", MomentumCalc.rsi(close), "rsi", from = LATE)

    @Test fun macdConverges() {
        val m = MomentumCalc.macd(close)
        check("MACD", m.line, "macd", from = LATE); check("MACD signal", m.signal, "macd_signal", from = LATE); check("MACD hist", m.hist, "macd_hist", from = LATE)
    }

    @Test fun stochasticMatchesExactly() {
        val s = MomentumCalc.stochastic(candles)
        check("fast %K", s.fastK, "stoch_k_fast", from = 1530)   // after the flat stretch (ta: NaN, mine: 50 by definition)
        check("slow %K", s.k, "stoch_d", from = 1530)            // ta's "signal" = SMA3 of fast %K = our slow %K
    }

    @Test fun stochRsiConverges() {
        val s = MomentumCalc.stochRsi(close)
        check("StochRSI raw", s.fastK, "stochrsi", from = LATE, tol = 1e-5, scale = 100.0)
        check("StochRSI %K", s.k, "stochrsi_k", from = LATE, tol = 1e-5, scale = 100.0)
        check("StochRSI %D", s.d, "stochrsi_d", from = LATE, tol = 1e-5, scale = 100.0)
    }

    @Test fun cciMatchesExactly() = check("CCI", MomentumCalc.cci(candles), "cci", from = 1550)   // ta divides by zero on the flat stretch

    @Test fun williamsMatchesExactly() = check("Williams %R", MomentumCalc.williamsR(candles), "williams_r", from = 1530)

    @Test fun ichimokuMatchesExactly() {
        val ich = TrendCalc.ichimoku(candles)
        check("Tenkan", ich.tenkan, "tenkan"); check("Kijun", ich.kijun, "kijun")
        check("Senkou A (raw)", ich.spanA, "span_a"); check("Senkou B (raw)", ich.spanB, "span_b")
    }

    @Test fun dmiMatchesExactly() {
        // ta emits 0.0 placeholders (not NaN) during warm-up: +DI/−DI before bar n + 1, ADX before bar 2n − 1.
        // Ours are null there. Wilder's running-sum smoothing (ta) and the RMA (ours) give identical DI ratios.
        val d = TrendCalc.dmi(candles, 14)
        check("+DI", d.plusDi, "plus_di", from = 15); check("−DI", d.minusDi, "minus_di", from = 15)
        check("ADX", d.adx, "adx", from = 27)
    }

    @Test fun psarMatchesReference()= check("PSAR", TrendCalc.psar(candles).value, "psar", from = 2)

    @Test fun mfiMatchesExactly() = check("MFI", VolumeCalc.mfi(candles), "mfi", from = 1550)

    // Cumulative sum of ~3,000 large terms: summation-order rounding reaches ~3e-9 relative, so 1e-7 is the bound.
    @Test fun adLineMatchesExactly() = check("A/D", VolumeCalc.accumulationDistribution(candles), "adl", tol = 1e-7)

    @Test fun obvChangesMatch() {
        // Two documented convention differences: ta starts at +V0 (we start at 0), and ta adds +V on an UNCHANGED
        // close (np.where(close < prev, −V, +V)); Granville's definition, used here, leaves OBV unchanged.
        val mine = VolumeCalc.obv(candles)
        val theirs = ref.getValue("obv")
        var unchanged = 0
        for (i in 1 until candles.size) {
            val dm = mine[i] - mine[i - 1]
            val dt = theirs[i]!! - theirs[i - 1]!!
            if (candles[i].close == candles[i - 1].close) {
                unchanged++
                if (dm != 0.0) fail("OBV must not move on an unchanged close (bar $i)")
            } else if (abs(dm - dt) > 1e-6) fail("OBV change at bar $i: mine=$dm ta=$dt")
        }
        assertTrue("fixture should contain unchanged closes (flat stretch)", unchanged >= 20)
    }

    @Test fun anchoredVwapMatchesPandasCumulative() = check("AVWAP", VolumeCalc.anchoredVwap(candles, 2000), "avwap2000", tol = 1e-9)
}
